const year = flow.get("selected_year");
const month = flow.get("selected_month");
const day = flow.get("selected_day"); // vamos setar isto no onDaySelected
const week = flow.get("selected_week");
if (!year) {
    node.error("Selecciona um ano antes de carregar as estatísticas");
    return null;
}

let url = null;
if (year && !month) {
    // somente ano
    url = `http://app:8000/stats/year/${year}`;
} else if (year && month && !week) {
    // ano + mês
    url = `http://app:8000/stats/month/${year}/${month}`;
} else if (year && month && week && !day) {
    // ano + mês + dia
    url = `http://app:8000/stats/week/${year}/${month}/${week}`;
} else if(year && month && week && day){
    url = `http://app:8000/stats/day/${year}/${month}/${week}/${day}`;
} else {
    // caso improvável — default para ano
    url = `http://app:8000/stats/year/${year}`;
}

msg.method = "GET";
msg.url = url;
return msg;

const day = msg.payload;
flow.set("selected_day", day);
return msg;

